SELECT
    user_id, union_id, open_id, nick_name, avatar as avatarUrl, phonenumber, password, status, login_ip, login_date, create_time, update_time
FROM sys_user

    status = 0

        AND user_id = #{userId}


        AND phonenumber like concat('%', #{phone}, '%')


        AND nick_name like concat('%', #{nickname}, '%')


        AND open_id  = #{openid}


        AND union_id  = #{unionid}
